    // ── About Page ──────────────────────────────────────────────────────────
    aboutBadge: "About us",
    aboutTitle: "We're building Rwanda's modern transport platform",
    aboutSubtitle:
      "Rugendo Rwanda is an online intercity bus booking platform designed for Rwandan travellers — simple to use, reliable, and built for how people actually travel today.",
    aboutMissionBadge: "Our mission",
    aboutMissionTitle: "Making intercity travel as easy as sending a message",
    aboutMissionP1:
      "Every day, thousands of Rwandans travel between cities for work, family, and opportunity. The process of finding a bus, booking a seat, and confirming your journey should not be complicated.",
    aboutMissionP2:
      "Rugendo Rwanda brings scheduling, seat booking, and digital boarding together in one platform — accessible from any phone, at any time.",
    aboutStat1: "Routes covered",
    aboutStat2: "Daily departures",
    aboutStat3: "Cities connected",
    aboutStat4: "Partner operators",
    aboutValuesTitle: "What we stand for",
    aboutValue1Title: "Connecting Rwanda",
    aboutValue1Desc:
      "Every Rwandan deserves a simple, dignified way to travel between cities — without long queues or uncertainty.",
    aboutValue2Title: "Digital-first convenience",
    aboutValue2Desc:
      "From booking to boarding, everything is digital. No paper tickets, no cash lines, no guessing.",
    aboutValue3Title: "Trust & transparency",
    aboutValue3Desc:
      "Clear pricing, confirmed bookings, and secure payments. No hidden fees, no surprises.",
    aboutValue4Title: "Supporting local operators",
    aboutValue4Desc:
      "We work with Rwandan bus companies to help them reach more passengers and operate better.",
    aboutCtaTitle: "Join thousands of Rwandan travellers",
    aboutCtaSubtitle:
      "Book your next intercity trip online — fast, safe, and simple.",
