    aboutSubtitle:
      "Rugendo Rwanda ni urubuga rwa interineti rwo kubika amatike ya bisi za mujyi rugenewe abagenzi b'Abanyarwanda — yoroshye gukoresha, zizekanye, kandi rugezwaho uburyo abantu bagenda.",
