    // ── FAQ Page ──────────────────────────────────────────────────────────────
    faqBadge: "Centre d'aide",
    faqTitle: "Questions fréquemment posées",
    faqSubtitle:
      "Réponses aux questions les plus courantes sur la réservation, le paiement et l'embarquement.",
    faqNotFound: "Vous n'avez pas trouvé ce que vous cherchiez ?",
    faqContactSupport: "Contacter le support",
    faqCat1: "Réservation",
    faqCat2: "Paiement",
    faqCat3: "Embarquement & billets",
    faqCat4: "Modifications & annulations",
    faqB1Q: "Comment réserver un billet de bus ?",
    faqB1A:
      "Recherchez votre trajet sur la page d'accueil ou la page Rechercher des trajets, choisissez un horaire, sélectionnez votre siège, payez et recevez votre billet. L'ensemble du processus prend moins de 2 minutes.",
    faqB2Q: "Dois-je avoir un compte pour réserver ?",
    faqB2A:
      "Oui. Vous avez besoin d'un compte gratuit Rugendo Rwanda pour effectuer une réservation. Cela nous permet de stocker votre référence et de vous envoyer des confirmations.",
    faqB3Q: "Puis-je réserver pour une autre personne ?",
    faqB3A:
      "Oui. Lors de la réservation, vous pouvez entrer un nom de passager différent. Vous gérez la réservation via votre propre compte.",
    faqB4Q: "Combien de temps à l'avance puis-je réserver ?",
    faqB4A:
      "Vous pouvez réserver jusqu'à 30 jours à l'avance. Les réservations du jour sont disponibles tant qu'il reste des places.",
    faqB5Q: "Puis-je réserver plusieurs places à la fois ?",
    faqB5A:
      "Oui. Sélectionnez le nombre de passagers lors de la recherche, et vous pouvez réserver plusieurs places en une seule transaction.",
    faqP1Q: "Quels modes de paiement sont acceptés ?",
    faqP1A:
      "MTN Mobile Money, Airtel Money et les principales cartes bancaires sont acceptés.",
    faqP2Q: "Est-il sûr de payer en ligne ?",
    faqP2A:
      "Oui. Les paiements sont traités via des canaux chiffrés et de confiance. Rugendo Rwanda ne stocke pas vos identifiants de carte ou de mobile money.",
    faqP3Q: "Quand ma carte ou mobile money est-elle débitée ?",
    faqP3A:
      "Le paiement est traité immédiatement au moment de la réservation. Votre siège n'est confirmé qu'une fois le paiement réussi.",
    faqP4Q:
      "J'ai été débité mais je n'ai pas reçu de confirmation. Que faire ?",
    faqP4A:
      "Contactez notre équipe d'assistance avec votre numéro de téléphone et les détails du paiement. Nous tracerons la transaction et confirmerons votre réservation ou émettrons un remboursement dans les 24 heures.",
    faqT1Q: "Qu'est-ce qu'un billet de réservation ?",
    faqT1A:
      "Un billet de réservation (numéro de référence) est un code unique reçu après une réservation réussie. Vous le présentez au parc de bus pour que l'opérateur puisse vérifier votre réservation.",
    faqT2Q: "Dois-je imprimer mon billet ?",
    faqT2A:
      "Non. Montrez votre référence de réservation sur votre téléphone. Un affichage numérique suffit.",
    faqT3Q: "Combien de temps à l'avance dois-je arriver au parc de bus ?",
    faqT3A:
      "Nous recommandons d'arriver au moins 20 minutes avant le départ pour la vérification d'embarquement.",
    faqC1Q: "Puis-je annuler ma réservation ?",
    faqC1A:
      "Les politiques d'annulation varient selon l'opérateur. Vérifiez les détails de la réservation dans votre compte ou contactez le support. Les annulations effectuées plus de 2 heures avant le départ donnent généralement droit à un remboursement.",
    faqC2Q: "Puis-je changer ma date de voyage ?",
    faqC2A:
      "La reprogrammation dépend de la politique de l'opérateur. Contactez notre équipe d'assistance avec votre référence de réservation et la nouvelle date souhaitée.",
    faqC3Q: "Que se passe-t-il si l'opérateur annule le bus ?",
    faqC3A:
      "Si un opérateur annule un départ prévu, tous les passagers concernés sont notifiés et reçoivent un remboursement complet.",

    // ── How It Works ──────────────────────────────────────────────────────────
    howBadge: "Simple et clair",
    howTitle: "Comment fonctionne Rugendo Rwanda",
    howSubtitle:
      "De la recherche d'un trajet à l'embarquement — voici exactement comment fonctionne le processus de réservation.",
    howStep1Title: "Créez votre compte",
    howStep1Desc:
      "Inscrivez-vous avec votre e-mail et votre numéro de téléphone. Cela prend moins d'une minute. Votre compte stocke vos voyages et vos données personnelles en toute sécurité.",
    howStep1Detail:
      "Aucune réservation n'est requise pour créer un compte. Vous pouvez rechercher et consulter les horaires sans vous inscrire.",
    howStep2Title: "Recherchez votre trajet",
    howStep2Desc:
      "Entrez votre ville de départ, votre destination et votre date de voyage. Sélectionnez le nombre de passagers.",
    howStep2Detail:
      "Vous pouvez rechercher des trajets comme Kigali → Butare, Kigali → Musanze, Butare → Gisenyi, et bien d'autres. Les horaires sont mis à jour en temps réel.",
    howStep3Title: "Choisissez un horaire",
    howStep3Desc:
      "Consultez tous les bus disponibles pour votre trajet et votre date. Comparez les heures de départ, les opérateurs, la classe de bus, les places disponibles et le prix.",
    howStep3Detail:
      "Chaque annonce affiche la compagnie de bus, le type de bus (standard/express/luxe) et les places restantes. Sélectionnez celle qui vous convient le mieux.",
    howStep4Title: "Choisissez votre place",
    howStep4Desc:
      "Choisissez un siège spécifique sur le plan du bus ou laissez le système vous attribuer le prochain disponible.",
    howStep4Detail:
      "Les sièges côté fenêtre, côté couloir et les rangées proches de l'avant sont tous sélectionnables si disponibles.",
    howStep5Title: "Payez en toute sécurité",
    howStep5Desc:
      "Payez via MTN Mobile Money, Airtel Money ou une carte bancaire. Le paiement est confirmé instantanément.",
    howStep5Detail:
      "Vous recevrez une confirmation de paiement sur votre téléphone immédiatement après la transaction.",
    howStep6Title: "Recevez votre billet",
    howStep6Desc:
      "Votre réservation est confirmée. Vous recevez un numéro de référence unique (jeton) par SMS et dans votre tableau de bord.",
    howStep6Detail:
      "Présentez cette référence au parc de bus — l'opérateur la scanne ou la vérifie pour valider votre embarquement. Pas besoin d'imprimer.",
    howFaqTitle: "Questions courantes",
    howFaq1Q: "Puis-je réserver pour quelqu'un d'autre ?",
    howFaq1A:
      "Oui. Lors de la réservation, vous pouvez entrer un nom de passager différent. Vous gérez la réservation via votre propre compte.",
    howFaq2Q: "Que faire si je rate mon bus ?",
    howFaq2A:
      "Contactez directement l'opérateur ou notre équipe d'assistance. Les politiques de re-réservation dépendent de l'opérateur et du temps restant avant le départ.",
    howFaq3Q: "Combien de temps avant dois-je arriver au parc de bus ?",
    howFaq3A:
      "Nous recommandons d'arriver au moins 20 minutes avant le départ pour la vérification d'embarquement.",
    howFaq4Q: "Que se passe-t-il si le bus est annulé ?",
    howFaq4A:
      "Si un opérateur annule un horaire, vous serez notifié et un remboursement sera traité vers votre méthode de paiement.",
    howFaq5Q: "Ma réservation est-elle garantie ?",
    howFaq5A:
      "Oui. Une fois le paiement confirmé, votre place est réservée. Le jeton de réservation est la preuve de votre réservation.",
    howCtaTitle: "Prêt à réserver votre voyage ?",
    howCtaSubtitle: "Créez un compte en moins d'une minute.",
    howCtaCreate: "Créer un compte",
