    // ── FAQ Page ──────────────────────────────────────────────────────────────
    faqBadge: "Kituo cha msaada",
    faqTitle: "Maswali yanayoulizwa mara kwa mara",
    faqSubtitle:
      "Majibu ya maswali ya kawaida zaidi kuhusu hifadhi, malipo, na kupanda.",
    faqNotFound: "Hukupata ulichotafuta?",
    faqContactSupport: "Wasiliana na msaada",
    faqCat1: "Hifadhi",
    faqCat2: "Malipo",
    faqCat3: "Kupanda & tikiti",
    faqCat4: "Mabadiliko & kughairi",
    faqB1Q: "Ninawezaje kuhifadhi tikiti ya basi?",
    faqB1A:
      "Tafuta njia yako kwenye ukurasa wa nyumbani au ukurasa wa Tafuta Safari, chagua ratiba, chagua kiti chako, lipa, na upokee tikiti yako. Mchakato mzima huchukua chini ya dakika 2.",
    faqB2Q: "Ninahitaji akaunti kuhifadhi?",
    faqB2A:
      "Ndiyo. Unahitaji akaunti ya bure ya Rugendo Rwanda kukamilisha hifadhi. Hii inatuwezesha kuhifadhi kumbukumbu yako na kukutumia uthibitisho.",
    faqB3Q: "Ninaweza kuhifadhi kwa mtu mwingine?",
    faqB3A:
      "Ndiyo. Unapohifadhi, unaweza kuweka jina tofauti la abiria. Unasimamia hifadhi kupitia akaunti yako mwenyewe.",
    faqB4Q: "Ninaweza kuhifadhi mapema kiasi gani?",
    faqB4A:
      "Unaweza kuhifadhi hadi siku 30 mapema. Hifadhi za siku hiyo hiyo zinapatikana viti vikiwa bado.",
    faqB5Q: "Ninaweza kuhifadhi viti vingi mara moja?",
    faqB5A:
      "Ndiyo. Chagua idadi ya abiria unapotafuta, na unaweza kuhifadhi viti vingi katika muamala mmoja.",
    faqP1Q: "Njia gani za malipo zinakubaliwa?",
    faqP1A:
      "MTN Mobile Money, Airtel Money, na kadi kuu za benki zinakubaliwa.",
    faqP2Q: "Je, ni salama kulipa mtandaoni?",
    faqP2A:
      "Ndiyo. Malipo yanachakatwa kupitia njia zilizofichwa na za kuaminika. Rugendo Rwanda haihifadhi nambari zako za kadi au pesa za simu.",
    faqP3Q: "Kadi yangu au pesa za simu zinatozwa lini?",
    faqP3A:
      "Malipo yanachakatwa mara moja wakati wa kuhifadhi. Kiti chako kinathibitishwa tu malipo yakifanikiwa.",
    faqP4Q: "Nilitoza lakini sikupokea uthibitisho wa hifadhi. Nifanye nini?",
    faqP4A:
      "Wasiliana na timu yetu ya msaada na nambari yako ya simu na maelezo ya malipo. Tutafuatilia muamala na kuthibitisha hifadhi yako au kutoa marejesho ndani ya masaa 24.",
    faqT1Q: "Tokeni ya hifadhi ni nini?",
    faqT1A:
      "Tokeni ya hifadhi (nambari ya kumbukumbu) ni nambari ya kipekee unayopokea baada ya hifadhi iliyofanikiwa. Unawasilisha kwenye kituo cha basi ili mwendeshaji aweze kuthibitisha nafasi yako.",
    faqT2Q: "Ninahitaji kuchapisha tikiti yangu?",
    faqT2A:
      "Hapana. Onyesha kumbukumbu yako ya hifadhi kwenye simu yako. Onyesho la dijitali linatosha.",
    faqT3Q: "Nifike lini kituo cha basi?",
    faqT3A:
      "Tunapendekeza kufika angalau dakika 20 kabla ya kuondoka kwa uthibitisho wa upandaji.",
    faqC1Q: "Ninaweza kughairi hifadhi yangu?",
    faqC1A:
      "Sera za kughairi zinatofautiana kwa mwendeshaji. Angalia maelezo ya hifadhi katika akaunti yako au wasiliana na msaada. Kughairi zaidi ya masaa 2 kabla ya kuondoka kwa ujumla kunastahili marejesho.",
    faqC2Q: "Ninaweza kubadilisha tarehe yangu ya safari?",
    faqC2A:
      "Kupanga upya kunategemea sera ya mwendeshaji. Wasiliana na timu yetu ya msaada na kumbukumbu yako ya hifadhi na tarehe mpya unayotaka.",
    faqC3Q: "Nifanyeje mwendeshaji akighairi basi?",
    faqC3A:
      "Kama mwendeshaji akighairi kuondoka kulilopangwa, abiria wote walioathiriwa wataarifiwa na kupokea marejesho kamili.",

    // ── How It Works ──────────────────────────────────────────────────────────
    howBadge: "Rahisi na wazi",
    howTitle: "Jinsi Rugendo Rwanda inavyofanya kazi",
    howSubtitle:
      "Kutoka kutafuta njia hadi kupanda basi yako — hivi ndivyo mchakato wa kuhifadhi unavyofanya kazi.",
    howStep1Title: "Fungua akaunti yako",
    howStep1Desc:
      "Jisajili kwa barua pepe na nambari ya simu yako. Inachukua chini ya dakika moja. Akaunti yako inahifadhi safari zako na maelezo ya kibinafsi kwa usalama.",
    howStep1Detail:
      "Hakuna hifadhi inayohitajika kuunda akaunti. Unaweza kutafuta na kuona ratiba bila kusajiliwa.",
    howStep2Title: "Tafuta njia yako",
    howStep2Desc:
      "Weka mji wa kuondokea, uendapo, na tarehe ya safari. Chagua idadi ya abiria.",
    howStep2Detail:
      "Unaweza kutafuta njia kama Kigali → Butare, Kigali → Musanze, Butare → Gisenyi, na nyingi zaidi. Ratiba zinasasishwa wakati halisi.",
    howStep3Title: "Chagua ratiba",
    howStep3Desc:
      "Tazama mabasi yote yanayopatikana kwa njia na tarehe yako. Linganisha muda wa kuondoka, waendeshaji, darasa la basi, viti vilivyopo, na bei.",
    howStep3Detail:
      "Kila orodha inaonyesha kampuni ya basi, aina ya basi (kawaida/haraka/anasa), na viti vilivyobaki. Chagua inayokufaa zaidi.",
    howStep4Title: "Chagua kiti chako",
    howStep4Desc:
      "Chagua kiti maalum kutoka kwenye ramani ya viti vya basi, au acha mfumo ukupangie kiti kinachofuata kinaochopatikana.",
    howStep4Detail:
      "Viti vya dirisha, viti vya njia ya basi, na safu karibu na mbele vinaweza kuchaguliwa vinapopatikana.",
    howStep5Title: "Lipa kwa usalama",
    howStep5Desc:
      "Lipa ukitumia MTN Mobile Money, Airtel Money, au kadi ya benki. Malipo yanathibitishwa mara moja.",
    howStep5Detail:
      "Utapokea uthibitisho wa malipo kwenye simu yako mara baada ya muamala kukamilika.",
    howStep6Title: "Pokea tikiti yako",
    howStep6Desc:
      "Hifadhi yako imethibitishwa. Unapokea nambari ya kipekee ya hifadhi (tokeni) kwa SMS na kwenye dashibodi yako.",
    howStep6Detail:
      "Onyesha kumbukumbu hii kwenye kituo cha basi — mwendeshaji anisoma au kuiangalia kuthibitisha upandaji wako. Hakuna haja ya kuchapisha.",
    howFaqTitle: "Maswali ya kawaida",
    howFaq1Q: "Ninaweza kuhifadhi kwa mtu mwingine?",
    howFaq1A:
      "Ndiyo. Unapohifadhi, unaweza kuweka jina tofauti la abiria. Unasimamia hifadhi kupitia akaunti yako mwenyewe.",
    howFaq2Q: "Nifanyeje nikosa basi yangu?",
    howFaq2A:
      "Wasiliana na mwendeshaji moja kwa moja au fikia timu yetu ya msaada. Sera za kuhifadhi tena zinategemea mwendeshaji na muda uliobaki kabla ya kuondoka.",
    howFaq3Q: "Nifike lini kituo cha basi?",
    howFaq3A:
      "Tunapendekeza kufika angalau dakika 20 kabla ya kuondoka kwa uthibitisho wa upandaji.",
    howFaq4Q: "Nifanyeje basi ikighairiwa?",
    howFaq4A:
      "Kama mwendeshaji akighairi ratiba, utaarifiwa na marejesho yatachakatwa kwa njia yako ya malipo.",
    howFaq5Q: "Hifadhi yangu inadhaminika?",
    howFaq5A:
      "Ndiyo. Malipo yakisha kuthibitishwa, kiti chako kimetengwa. Tokeni ya hifadhi ni ushahidi wa hifadhi ya kiti chako.",
